package com.messaging.consumer

import java.util.concurrent.atomic.AtomicBoolean
import java.util.Base64
import javax.crypto.spec.SecretKeySpec
import javax.crypto.Mac
import java.security.{KeyFactory, Signature}
import java.security.spec.X509EncodedKeySpec
import scala.util.{Try, Success, Failure}
import scala.collection.mutable.ArrayBuffer

case class JwtHeader(alg: String, typ: String)
case class JwtPayload(sub: String, role: String, queue: String, exp: Long)
case class DecodedToken(header: JwtHeader, payload: JwtPayload, valid: Boolean)

trait TokenVerifier {
  def verify(token: String): DecodedToken
}

class AsymmetricVerifier(publicKeyPem: String) extends TokenVerifier {
  private val pubKeyBytes = Base64.getDecoder.decode(
    publicKeyPem.replaceAll("-----[A-Z ]+-----", "").replaceAll("\\s", "")
  )
  private val keySpec = new X509EncodedKeySpec(pubKeyBytes)
  private val keyFactory = KeyFactory.getInstance("RSA")
  private val publicKey = keyFactory.generatePublic(keySpec)

  override def verify(token: String): DecodedToken = {
    val parts = token.split("\\.")
    if (parts.length != 3) return DecodedToken(JwtHeader("", ""), JwtPayload("", "", "", 0), false)

    val headerJson = new String(Base64.getUrlDecoder.decode(parts(0)))
    val payloadJson = new String(Base64.getUrlDecoder.decode(parts(1)))
    val signature = Base64.getUrlDecoder.decode(parts(2))

    val header = parseHeader(headerJson)
    val payload = parsePayload(payloadJson)

    val isValid = verifySignature(header.alg, parts(0) + "." + parts(1), signature)
    val notExpired = payload.exp > System.currentTimeMillis() / 1000

    DecodedToken(header, payload, isValid && notExpired)
  }

  private def verifySignature(algorithm: String, data: String, signature: Array[Byte]): Boolean = {
    algorithm match {
      case "RS256" =>
        val sig = Signature.getInstance("SHA256withRSA")
        sig.initVerify(publicKey)
        sig.update(data.getBytes("UTF-8"))
        sig.verify(signature)
      case "HS256" =>
        // Fallback for legacy clients using symmetric signing
        val mac = Mac.getInstance("HmacSHA256")
        val secretKey = new SecretKeySpec(pubKeyBytes, "HmacSHA256")
        mac.init(secretKey)
        val computed = mac.doFinal(data.getBytes("UTF-8"))
        java.util.Arrays.equals(computed, signature)
      case _ => false
    }
  }

  private def parseHeader(json: String): JwtHeader = {
    val alg = extractField(json, "alg")
    val typ = extractField(json, "typ")
    JwtHeader(alg, typ)
  }

  private def parsePayload(json: String): JwtPayload = {
    val sub = extractField(json, "sub")
    val role = extractField(json, "role")
    val queue = extractField(json, "queue")
    val exp = Try(extractField(json, "exp").toLong).getOrElse(0L)
    JwtPayload(sub, role, queue, exp)
  }

  private def extractField(json: String, field: String): String = {
    val pattern = s""""$field"\s*:\s*"?([^"\},]+)"?""".r
    pattern.findFirstMatchIn(json).map(_.group(1)).getOrElse("")
  }
}

class MessageQueueConsumer(
  verifier: TokenVerifier,
  queueName: String,
  maxBatchSize: Int = 100
) {
  private val running = new AtomicBoolean(true)
  private val messageBuffer = ArrayBuffer.empty[String]
  private val processedCount = new java.util.concurrent.atomic.AtomicLong(0)

  def start(authToken: String): Unit = {
    val decoded = verifier.verify(authToken)
    if (!decoded.valid) {
      throw new SecurityException("Invalid authentication token")
    }
    if (decoded.payload.queue != queueName && decoded.payload.role != "admin") {
      throw new SecurityException(s"Token not authorized for queue: $queueName")
    }

    Runtime.getRuntime.addShutdownHook(new Thread(() => {
      gracefulShutdown()
    }))

    consumeLoop(decoded.payload)
  }

  private def consumeLoop(auth: JwtPayload): Unit = {
    while (running.get()) {
      Try {
        val messages = pollMessages(maxBatchSize)
        messages.foreach { msg =>
          messageBuffer += msg
          if (messageBuffer.size >= maxBatchSize) {
            flushBuffer(auth)
          }
        }
        Thread.sleep(100)
      } match {
        case Success(_) => ()
        case Failure(e) =>
          System.err.println(s"Error in consume loop: ${e.getMessage}")
          Thread.sleep(1000)
      }
    }
    flushBuffer(auth)
  }

  private def pollMessages(batch: Int): Seq[String] = {
    // Simulated message polling from broker
    Seq.empty[String]
  }

  private def flushBuffer(auth: JwtPayload): Unit = {
    if (messageBuffer.nonEmpty) {
      val batch = messageBuffer.toList
      messageBuffer.clear()
      processBatch(batch, auth)
    }
  }

  private def processBatch(messages: List[String], auth: JwtPayload): Unit = {
    messages.foreach { msg =>
      processedCount.incrementAndGet()
    }
  }

  def gracefulShutdown(): Unit = {
    running.set(false)
    System.err.println(s"Shutting down consumer. Processed: ${processedCount.get()} messages")
  }

  def isRunning: Boolean = running.get()
  def getProcessedCount: Long = processedCount.get()
}
